// Stage 5 preparation is separate from ordinary Engineer chat and feedback context.
(()=>{
 const section=document.createElement('section');section.id='preproof';section.innerHTML=`<h2>Whole-arrangement Master profile</h2><p>Import a full post-processing Master render: 48 kHz stereo WAV/AIFF. Scrunch measures every window locally. File coverage is verified; whole-arrangement provenance is your confirmation.</p><input id="masterFile" type="file" accept=".wav,.aif,.aiff"><label>Arrangement start (seconds)<input id="masterStart" type="number" min="0" value="0"></label><label><input id="masterConfirm" type="checkbox"> This is the complete post-processing Master render.</label><button id="masterBuild">Profile supplied Master</button><p id="masterStatus" role="status"></p><label>Saved Master profile<select id="profileId"><option value="">Choose a completed profile</option></select></label><button id="profileOpen">Open measured profile</button><h3>Evidence-linked findings · blind/reveal experiment</h3><p>Begin a fresh blind experiment before entering independent feedback. The context excludes ordinary chat, saved feedback and source filenames. This preparation workflow does not call or charge a model. A model reviewer can use the supplied context; no automatic provider execution is claimed.</p><button id="blindStart">Start blind review</button><div id="profileWindows"></div><label>Blind finding<textarea id="blindText"></textarea></label><label>Evidence confidence<select id="blindConfidence"><option value="tentative">Tentative</option><option value="supported">Supported by cited measurements</option><option value="not-supported">Not supported by measurements</option></select></label><button id="blindSeal">Seal blind finding</button><fieldset id="revealFields" disabled><legend>Reveal independent feedback after sealing</legend><textarea id="independentFeedback" placeholder="Paul’s independent comments"></textarea><button id="feedbackReveal">Reveal feedback</button></fieldset><div id="blindResult"></div><audio id="evidenceAudio" controls></audio><p>Navigation plays a conservative three-second cue from the local Master render. Live bar/beat navigation remains unverified; no transport or locator changes occur.</p><details><summary>Technical details / isolated reasoning context</summary><pre id="blindContext"></pre></details>`;
 document.getElementById('referenceWorkspace').append(section);const el=id=>document.getElementById(id);let sourceId=null,experiment=null,profile=null;
 async function post(path,body){const state=await fetch('/api/state').then(r=>r.json());const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Scrunch-Token':state.token},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
 async function act(fn){try{await fn()}catch(e){el('masterStatus').textContent=e.message}}
 async function library(){try{const r=await fetch('/api/profiles');if(!r.ok)return;const j=await r.json();if(j.errors?.length)el('masterStatus').textContent=j.errors.join(' ');for(const p of j.profiles||[])if(![...el('profileId').options].some(o=>o.value===p.id))el('profileId').add(new Option(p.name+' · '+p.durationSeconds.toFixed(1)+' s',p.id));}catch{}}library();
 el('masterBuild').onclick=()=>act(async()=>{const f=el('masterFile').files[0];if(!f||!el('masterConfirm').checked)throw Error('Choose and confirm the complete Master render.');const state=await fetch('/api/state').then(r=>r.json());let r=await fetch('/api/profile/upload',{method:'POST',headers:{'X-Scrunch-Token':state.token,'X-File-Name':encodeURIComponent(f.name)},body:f});let j=await r.json();if(!r.ok)throw Error(j.error);sourceId=j.sourceId;el('profileId').add(new Option(f.name+' — processing',sourceId));el('profileId').value=sourceId;await post('/api/profile/build',{sourceId,startSeconds:Number(el('masterStart').value),masterRenderConfirmed:true});el('masterStatus').textContent='Profiling locally in background. This job survives as a visible interrupted record if the server stops; it is never silently retried.'});
 async function open(){const id=el('profileId').value.trim();const r=await fetch('/api/profile/'+encodeURIComponent(id));const j=await r.json();if(!r.ok)throw Error(j.error);profile=j;el('masterStatus').textContent=`${j.windows.length} windows · ${j.coverage}`;const list=el('profileWindows');list.replaceChildren();const select=document.createElement('select');select.id='evidenceWindow';for(const w of j.windows)select.add(new Option(`${w.startSeconds.toFixed(2)}–${w.endSeconds.toFixed(2)} s · ${w.integratedLUFS===null?'unmeasurable':w.integratedLUFS.toFixed(1)+' LUFS'}`,w.id));const cue=document.createElement('button');cue.textContent='Jump / listen to selected evidence';cue.onclick=()=>act(async()=>{const response=await fetch(`/api/profile/${id}/cue/${select.value}`);if(!response.ok)throw Error('Measured audio changed or cue unavailable.');const a=el('evidenceAudio');if(a.src.startsWith('blob:'))URL.revokeObjectURL(a.src);a.src=URL.createObjectURL(await response.blob());await a.play()});list.append(select,cue);el('blindContext').textContent=JSON.stringify(j,null,2)}
 function inline(){if(!profile)return;document.getElementById('inlineProfile')?.remove();const card=document.createElement('section');card.id='inlineProfile';const title=document.createElement('p');title.textContent=`Master profile · ${profile.windows.length} measured windows · snapshot of supplied render`;const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=180;canvas.setAttribute('aria-label','Master loudness by time; measured window snapshots');card.append(title,canvas);const button=document.createElement('button');button.textContent='Inspect evidence and navigate';button.onclick=()=>document.getElementById('tabReference').click();card.append(button);document.getElementById('engineerChat').append(card);const x=canvas.getContext('2d');x.fillStyle='#adbbb5';x.font='13px sans-serif';x.fillText('Window integrated LUFS (original levels; not whole-song integrated)',12,18);const rows=profile.windows;rows.forEach((w,i)=>{if(w.integratedLUFS===null)return;const h=Math.max(0,Math.min(120,(w.integratedLUFS+60)*2));x.fillStyle='#e99c43';x.fillRect(12+i*976/rows.length,150-h,Math.max(1,976/rows.length),h)});x.fillStyle='#adbbb5';x.fillText(rows[0].startSeconds.toFixed(2)+' s',12,175);x.fillText(rows.at(-1).endSeconds.toFixed(2)+' s',900,175)}
 el('profileOpen').onclick=()=>act(async()=>{await open();inline()});
 el('blindStart').onclick=()=>act(async()=>{await open();const j=await post('/api/experiment/create',{profileId:profile.profileId});experiment=j.id;el('blindText').value='';el('independentFeedback').value='';el('revealFields').disabled=true;el('blindSeal').disabled=false;el('blindContext').textContent=JSON.stringify(j.context,null,2);el('blindResult').textContent='Blind review started. Independent feedback is excluded.'});
 el('blindSeal').onclick=()=>act(async()=>{if(!experiment||!profile)throw Error('Start blind review first.');const confidence=el('blindConfidence').value;const j=await post('/api/experiment/seal',{id:experiment,profileId:profile.profileId,findings:[{text:el('blindText').value,windowIds:confidence==='not-supported'?[]:[el('evidenceWindow').value],confidence}]});el('blindResult').textContent=j.findings.map(f=>f.text+' — '+f.confidence).join('\n');el('blindSeal').disabled=true;el('revealFields').disabled=false});
 el('feedbackReveal').onclick=()=>act(async()=>{const j=await post('/api/experiment/reveal',{id:experiment,feedback:el('independentFeedback').value});el('blindContext').textContent=JSON.stringify(j.context,null,2);el('revealFields').disabled=true;el('blindResult').append(document.createTextNode(' Independent feedback revealed; sealed blind finding retained.'))});
 setInterval(async()=>{if(!sourceId)return;try{const r=await fetch('/api/reference/state');if(!r.ok)return;const {job}=await r.json();if(job?.parameters?.sourceId===sourceId&&['complete','failed','interrupted'].includes(job.status)){el('masterStatus').textContent=job.result?.message||job.error||job.status;if(job.status==='complete'){await open();inline();}sourceId=null}}catch{}},3000);
})();
